import React, { useState, useEffect, useRef } from 'react';
import { getUserRoles } from '../../keycloak';
import './MainFeed.css';

const MainFeed = () => {
    const [posts, setPosts] = useState([]);
    const [newPost, setNewPost] = useState({ type: 'text', title: '', content: '', url: '' });
    const [showAddForm, setShowAddForm] = useState(false);
    const [userRoles, setUserRoles] = useState([]);
    const [playingAudioId, setPlayingAudioId] = useState(null);
    const [volume, setVolume] = useState(0.7);
    const [playbackRate, setPlaybackRate] = useState(1.0);
    const audioRef = useRef(null);
    const feedEndRef = useRef(null);
    const feedContainerRef = useRef(null);

    useEffect(() => {
        // Загружаем сохраненные посты из localStorage
        const savedPosts = localStorage.getItem('mainFeedPosts');
        if (savedPosts) {
            setPosts(JSON.parse(savedPosts));
        } else {
            // Начальные данные (старые сверху, новые снизу)
            const initialPosts = [
                {
                    id: 1,
                    type: 'text',
                    title: 'О стремлении человека не есть',
                    content: 'Понимание истинных потребностей тела и духа. Человек может существовать без физической пищи, черпая энергию из духовных источников.',
                    date: '2025-03-15',
                    author: 'Admin'
                },
                {
                    id: 2,
                    type: 'text',
                    title: 'Основа сила человека - дух',
                    content: 'Духовная сила - это основа всего. Развивая дух, мы развиваем себя.',
                    date: '2025-03-16',
                    author: 'Admin'
                },
                {
                    id: 3,
                    type: 'audio',
                    title: 'Эфир - 01.01.2025',
                    content: 'Новогодний эфир. Подведение итогов и планы на будущее.',
                    url: '/audio/efir-01-01-2025.mp3',
                    date: '2025-01-01',
                    author: 'Admin'
                },
                {
                    id: 4,
                    type: 'audio',
                    title: 'Эфир - 13.01.2025',
                    content: 'Практики дыхания и медитации.',
                    url: '/audio/efir-13-01-2025.mp3',
                    date: '2025-01-13',
                    author: 'Admin'
                },
                {
                    id: 5,
                    type: 'audio',
                    title: 'Эфир - 22.01.2025',
                    content: 'Сила движения и его значение в жизни.',
                    url: '/audio/efir-22-01-2025.mp3',
                    date: '2025-01-22',
                    author: 'Admin'
                },
                {
                    id: 6,
                    type: 'audio',
                    title: 'Эфир - 31.01.2025',
                    content: 'Заключительный эфир месяца. Ответы на вопросы.',
                    url: '/audio/efir-31-01-2025.mp3',
                    date: '2025-01-31',
                    author: 'Admin'
                },
                {
                    id: 7,
                    type: 'text',
                    title: 'Значение движения',
                    content: 'Движение - это жизнь. Ежедневная физическая активность необходима для поддержания здоровья и энергии.',
                    date: '2025-03-17',
                    author: 'Admin'
                },
                {
                    id: 8,
                    type: 'text',
                    title: 'Дыхание - основа жизни человека',
                    content: 'Правильное дыхание - ключ к здоровью и долголетию. Практики осознанного дыхания.',
                    date: '2025-03-18',
                    author: 'Admin'
                },
                {
                    id: 9,
                    type: 'text',
                    title: 'О силе человека',
                    content: 'Источники внутренней силы. Как развивать и сохранять силу духа.',
                    date: '2025-03-19',
                    author: 'Admin'
                }
            ];
            setPosts(initialPosts);
            localStorage.setItem('mainFeedPosts', JSON.stringify(initialPosts));
        }

        // Проверяем права пользователя
        const roles = getUserRoles();
        setUserRoles(roles);
    }, []);

    // Автоматически скроллим к последней записи (вниз) при загрузке
    useEffect(() => {
        if (feedEndRef.current) {
            feedEndRef.current.scrollIntoView({ behavior: 'auto' });
        }
    }, [posts]);

    useEffect(() => {
        if (audioRef.current) {
            audioRef.current.volume = volume;
            audioRef.current.playbackRate = playbackRate;
        }
    }, [volume, playbackRate]);

    const isAdmin = userRoles.includes('admin');

    const handleAddPost = () => {
        if (!newPost.title || !newPost.content) {
            alert('Заполните заголовок и содержание');
            return;
        }

        const post = {
            id: Date.now(),
            ...newPost,
            date: new Date().toISOString().split('T')[0],
            author: 'Admin'
        };

        const updatedPosts = [...posts, post]; // Добавляем в конец (новое снизу)
        setPosts(updatedPosts);
        localStorage.setItem('mainFeedPosts', JSON.stringify(updatedPosts));

        setNewPost({ type: 'text', title: '', content: '', url: '' });
        setShowAddForm(false);

        // Скроллим к новой записи
        setTimeout(() => {
            if (feedEndRef.current) {
                feedEndRef.current.scrollIntoView({ behavior: 'smooth' });
            }
        }, 100);
    };

    const handleDeletePost = (id) => {
        if (window.confirm('Удалить эту запись?')) {
            const updatedPosts = posts.filter(post => post.id !== id);
            setPosts(updatedPosts);
            localStorage.setItem('mainFeedPosts', JSON.stringify(updatedPosts));
            if (playingAudioId === id) {
                setPlayingAudioId(null);
            }
        }
    };

    const handlePlayAudio = (postId, audioUrl) => {
        if (playingAudioId === postId) {
            if (audioRef.current) {
                if (audioRef.current.paused) {
                    audioRef.current.play();
                } else {
                    audioRef.current.pause();
                }
            }
        } else {
            setPlayingAudioId(postId);
            setTimeout(() => {
                if (audioRef.current) {
                    audioRef.current.src = audioUrl;
                    audioRef.current.play();
                }
            }, 100);
        }
    };

    const handleStopAudio = () => {
        if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current.src = '';
        }
        setPlayingAudioId(null);
    };

    const handleVolumeChange = (e) => {
        setVolume(parseFloat(e.target.value));
    };

    const handleSpeedChange = (e) => {
        setPlaybackRate(parseFloat(e.target.value));
    };

    const togglePlayPause = () => {
        if (audioRef.current) {
            if (audioRef.current.paused) {
                audioRef.current.play();
            } else {
                audioRef.current.pause();
            }
        }
    };

    return (
        <div className="main-feed">
            <div className="feed-header">
                <h2>📰 Лента проекта "Путь Сердца"</h2>
                <p>Свежие записи внизу, архивные вверху</p>
            </div>

            <div className="feed-container" ref={feedContainerRef}>
                <div className="feed-list">
                    {posts.map((post) => (
                        <div key={post.id} className="feed-post">
                            <div className="post-header">
                                <div className="post-type">
                                    {post.type === 'text' && '📄'}
                                    {post.type === 'audio' && '🎵'}
                                    {post.type === 'video' && '🎬'}
                                </div>
                                <div className="post-title">{post.title}</div>
                                {isAdmin && (
                                    <button
                                        className="delete-post"
                                        onClick={() => handleDeletePost(post.id)}
                                    >
                                        🗑️
                                    </button>
                                )}
                            </div>

                            <div className="post-date">{post.date}</div>
                            <div className="post-content">{post.content}</div>

                            {post.type === 'audio' && (
                                <div className="post-audio">
                                    {playingAudioId === post.id ? (
                                        <div className="audio-player-inline">
                                            <div className="audio-controls">
                                                <button className="play-pause-btn" onClick={togglePlayPause}>
                                                    {audioRef.current && !audioRef.current.paused ? '⏸️' : '▶️'}
                                                </button>
                                                <button className="stop-btn" onClick={handleStopAudio}>
                                                    ⏹️
                                                </button>
                                                <div className="audio-info">
                                                    Сейчас играет: {post.title}
                                                </div>
                                            </div>
                                            <div className="audio-settings">
                                                <div className="volume-control">
                                                    <span>🔊</span>
                                                    <input
                                                        type="range"
                                                        min="0"
                                                        max="1"
                                                        step="0.01"
                                                        value={volume}
                                                        onChange={handleVolumeChange}
                                                        className="volume-slider"
                                                    />
                                                </div>
                                                <div className="speed-control">
                                                    <span>⚡</span>
                                                    <select value={playbackRate} onChange={handleSpeedChange} className="speed-select">
                                                        <option value="0.5">0.5x</option>
                                                        <option value="0.75">0.75x</option>
                                                        <option value="1.0">1.0x</option>
                                                        <option value="1.25">1.25x</option>
                                                        <option value="1.5">1.5x</option>
                                                        <option value="2.0">2.0x</option>
                                                    </select>
                                                </div>
                                            </div>
                                        </div>
                                    ) : (
                                        <button className="play-audio" onClick={() => handlePlayAudio(post.id, post.url)}>
                                            ▶️ Слушать эфир
                                        </button>
                                    )}
                                </div>
                            )}

                            {post.type === 'video' && post.url && (
                                <div className="post-video">
                                    <video controls width="100%">
                                        <source src={post.url} type="video/mp4" />
                                        Ваш браузер не поддерживает видео
                                    </video>
                                </div>
                            )}
                        </div>
                    ))}
                    <div ref={feedEndRef} className="feed-end-marker" />
                </div>

                {isAdmin && (
                    <div className="admin-section">
                        <div className="admin-controls">
                            <button
                                className="add-post-button"
                                onClick={() => setShowAddForm(!showAddForm)}
                            >
                                {showAddForm ? '✖ Отмена' : '+ Добавить запись'}
                            </button>
                        </div>

                        {showAddForm && (
                            <div className="add-post-form">
                                <h3>Новая запись</h3>
                                <select
                                    value={newPost.type}
                                    onChange={(e) => setNewPost({...newPost, type: e.target.value})}
                                >
                                    <option value="text">Текст</option>
                                    <option value="audio">Аудио (эфир)</option>
                                    <option value="video">Видео</option>
                                </select>

                                <input
                                    type="text"
                                    placeholder="Заголовок"
                                    value={newPost.title}
                                    onChange={(e) => setNewPost({...newPost, title: e.target.value})}
                                />

                                <textarea
                                    placeholder="Содержание"
                                    value={newPost.content}
                                    onChange={(e) => setNewPost({...newPost, content: e.target.value})}
                                    rows="4"
                                />

                                {(newPost.type === 'audio' || newPost.type === 'video') && (
                                    <input
                                        type="text"
                                        placeholder="URL файла (например: /audio/efir.mp3)"
                                        value={newPost.url}
                                        onChange={(e) => setNewPost({...newPost, url: e.target.value})}
                                    />
                                )}

                                <button onClick={handleAddPost}>Опубликовать</button>
                            </div>
                        )}
                    </div>
                )}
            </div>

            <audio ref={audioRef} style={{ display: 'none' }} />
        </div>
    );
};

export default MainFeed;
